const entrada = $json;

// A resposta do AI Agent normalmente vem em "output".
// Deixamos alternativas para tornar o fluxo mais resistente.
let raw =
  entrada.output ??
  entrada.text ??
  entrada.response ??
  entrada;

// Se já for objeto, usa diretamente.
// Se for string, converte para JSON.
let dados;

if (typeof raw === 'object' && raw !== null) {
  dados = raw;
} else {
  let texto = String(raw || '').trim();

  // Remove ```json ... ``` caso o modelo envie markdown por engano
  texto = texto
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  // Tenta pegar somente o objeto JSON
  const inicio = texto.indexOf('{');
  const fim = texto.lastIndexOf('}');

  if (inicio !== -1 && fim !== -1 && fim > inicio) {
    texto = texto.slice(inicio, fim + 1);
  }

  try {
    dados = JSON.parse(texto);
  } catch (error) {
    throw new Error(
      `Não foi possível converter a resposta do agente para JSON. Resposta recebida: ${texto}`
    );
  }
}

// Dados originais recebidos pelo WhatsApp
const dadosCliente = $('Padronizar mensagem do cliente').item.json;

const telefoneWhatsApp = String(
  dadosCliente.telefone || ''
).trim();

const mensagemUsuario = String(
  dadosCliente.mensagem_usuario || ''
).trim();

// Funções auxiliares
const texto = (valor) => {
  if (valor === null || valor === undefined) return '';
  return String(valor).trim();
};

const booleano = (valor) => {
  if (typeof valor === 'boolean') return valor;

  if (typeof valor === 'string') {
    return valor.trim().toLowerCase() === 'true';
  }

  return Boolean(valor);
};

// Valores permitidos
const intencoesPermitidas = [
  'solicitar_orcamento',
  'duvida_servico',


  'agendar_visita',
  'reagendar_visita',
  'cancelar_visita',
  'consultar_agendamento',

  'acompanhar_orcamento',

  // Cliente aprovou ou recusou o orçamento
  'aceitar_orcamento',
  'recusar_orcamento',
  'negociar_orcamento',
  'desistir_orcamento',
  'acompanhar_servico',
  'falar_com_humano',
  'outro',
];

const acoesAgendamentoPermitidas = [
  'nenhuma',
  'consultar_disponibilidade',
  'agendar',
  'reagendar',
  'cancelar',
  'consultar_agendamento',
];

const statusVisitaPermitidos = [
  '',
  'aguardando_disponibilidade',
  'aguardando_confirmacao',
  'agendada',
  'reagendamento_solicitado',
  'cancelamento_solicitado',
  'cancelada',
  'realizada',
];

// Normalização da intenção
let intencao = texto(dados.intencao);

if (!intencoesPermitidas.includes(intencao)) {
  intencao = 'outro';
}

// Normalização da ação de agendamento
let acaoAgendamento = texto(
  dados.acao_agendamento
);

if (!acoesAgendamentoPermitidas.includes(acaoAgendamento)) {
  acaoAgendamento = 'nenhuma';
}

// Normalização do status da visita
let statusVisita = texto(
  dados.status_visita
);

if (!statusVisitaPermitidos.includes(statusVisita)) {
  statusVisita = '';
}

// Retorno padronizado para o restante do workflow
return {
  json: {
    resposta_cliente: texto(
      dados.resposta_cliente
    ),

    intencao,

    precisa_humano: booleano(
      dados.precisa_humano
    ),

    nome: texto(
      dados.nome
    ),

    // Prioriza o número real que chegou pelo WhatsApp
    telefone:
      telefoneWhatsApp ||
      texto(dados.telefone),

    cidade: texto(
      dados.cidade
    ),

    bairro: texto(
      dados.bairro
    ),

    cep: texto(
      dados.cep
    ),

    endereco_servico: texto(
      dados.endereco_servico
    ),

    servico: texto(
      dados.servico
    ),

    medidas: texto(
      dados.medidas
    ),

    tipo_vidro: texto(
      dados.tipo_vidro
    ),

    cor_vidro: texto(
      dados.cor_vidro
    ),

    fotos_recebidas: booleano(
      dados.fotos_recebidas
    ),

    necessita_visita: booleano(
      dados.necessita_visita
    ),

    disponibilidade_cliente: texto(
      dados.disponibilidade_cliente
    ),

    acao_agendamento: acaoAgendamento,

    data_visita: texto(
      dados.data_visita
    ),

    horario_visita: texto(
      dados.horario_visita
    ),

    status_visita: statusVisita,

    prazo_desejado: texto(
      dados.prazo_desejado
    ),

    descricao: texto(
      dados.descricao
    ),

    resumo: texto(
      dados.resumo
    ),

    // Mantemos para uso em histórico e notificações
    mensagem_usuario: mensagemUsuario,
  },
};

